          label,
          id: folder_path,
        })

        let is_expanded = has(expanded_folders, folder_path)

        if (is_expanded) {
          append_children(children, `${folder_path}/`)
        }

        items.push(whitespace)
      }
    })
  }

  append_children(root)

  items = map(items, (item, index) => {
    if (item.type == 'whitespace' && items?.[index + 1]?.type == 'whitespace') {
      return
    }
    return item
  })

  return items
}

function render(md: string) {
  return marked.parse(md, {
    gfm: true,
    breaks: true,
  })
}

render = memoize(render)

let ws: WebSocket
let pending_actions: Set<fn> = set()
let pending_requests: Record<id, fn> = {}

function connect() {
  ws = new WebSocket('ws://localhost:8192/api/ws')

  ws.onopen = () => {
    log('Connected!')

    map(pending_actions, call)
  }

  ws.onmessage = receive

  ws.onclose = () => {
    log('Disconnected')

    const delay = ws_retry_delay + random() * ws_max_jitter

    set_timeout(function () {
      log('Reconnecting...')

      connect()
    }, delay)
  }
type textarea = {
  value: string
  placeholder?: string
  set_value: (value: string | ((...args: any) => string)) => void
  [key: Key]: any
}

export function textarea({ value, set_value, ...props }: textarea) {
  const ref = useRef()

  function handle_change(event) {
    set_value(event.target.value)
  }

  useEffect(() => {
    const textarea = ref.current
    if (!textarea) return

    // 1. Temporarily hide scrollbar track to avoid flashing layouts
    const originalOverflow = textarea.style.overflowY
    textarea.style.overflowY = 'hidden'

    // 2. Reset height to 'auto' to allow the textarea to shrink if text was deleted
    textarea.style.height = 'auto'

    // 3. Capture the exact content height calculated by the browser engine
    let targetHeight = textarea.scrollHeight

    // Guard clause: If element is hidden or detached (0px), don't collapse it
    if (targetHeight === 0) {
      textarea.style.overflowY = originalOverflow
      return
    }

    // 4. Handle browser engine edge-cases where borders aren't added to scrollHeight
    const style = window.getComputedStyle(textarea)
    if (style.boxSizing === 'border-box') {
      const borderTop = parseFloat(style.borderTopWidth) || 0
      const borderBottom = parseFloat(style.borderBottomWidth) || 0

      if (textarea.clientHeight === targetHeight) {
        targetHeight += borderTop + borderBottom
      }
    }

    // 5. Apply the calculated height and restore overflow settings
    textarea.style.height = `${targetHeight}px`
    textarea.style.overflowY = originalOverflow
  }, [value])

  useEffect(() => {
    const handleResize = () => {
      const textarea = ref.current
      if (!textarea) return
      textarea.style.height = 'auto'
      textarea.style.height = `${textarea.scrollHeight}px`
    }

    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return h('textarea.textarea', {
    value,
    onchange: handle_change,
    ref,
    ...props,
  })
}
